// Standing in somebody else's language.
//
// Forty-three test gardeners, one per language the site knows, so that what a
// page looks like to a reader of Macedonian can be looked at rather than
// imagined. `Server/testers.json` is the roster and is generated by
// `tools/site/export.py` off the same manifest rows the chooser is built from,
// which is what keeps it from falling behind the languages.
//
// ## There are no accounts, and this is not a login
//
// Worth saying plainly at the top of the file that implements it. `Server/` is
// static files. Nothing here reaches an origin, there is no session, no record
// of who signed in and nothing to sign in *to* — the whole app is built on the
// property that a seed never leaves the phone it was drawn on, and adding a
// user table to the website would be the first thing to break it.
//
// So a tester is a name and a language held in this browser's local storage,
// and the password below is a **latch, not a lock**: it keeps the roster out of
// the way of somebody who wanders in, and it is readable by anybody who opens
// this file. That is fine, because the roster protects nothing. Every name on
// it is invented, the plants are invented, and the page already says so.
//
// If something on this site ever does need protecting, it needs a server, and
// this file is not the place it gets one.
//
// ## What a tester actually changes
//
// The language, and nothing else. That is not a small thing: the language
// settles which labels are drawn, which bank supplies the passage, which way
// the page runs, whether the label voice may be uppercased, and whether it may
// be letter-spaced. Arabic alone moves all five. Standing in a tester is
// standing where a reader of that language stands, which is what was asked for.
//
// The name is there so it is possible to tell at a glance which one you are in,
// and because `Test-AR-Bustani` says *Arabic* faster than a two-letter code
// does.

/// The shared latch. See the note above about what this is and is not.
export const PASSWORD = "peace";

const STORAGE_KEY = "site.tester.v1";
const UNLOCK_KEY = "site.tester.unlocked.v1";

let rosterPromise = null;

/// The generated roster. A fetch that fails reads as an empty roster rather
/// than an error, for the same reason a missing label falls back to English in
/// silence: the site is a garden, not a console.
export function roster() {
  if (!rosterPromise) {
    rosterPromise = fetch("/testers.json", { cache: "force-cache" })
      .then((response) => (response.ok ? response.json() : null))
      .then((file) => (file && Array.isArray(file.testers) ? file.testers : []))
      .catch(() => []);
  }
  return rosterPromise;
}

/// Storage that is unavailable reads as nobody signed in, which is the right
/// answer rather than an error. Same rule as `languages.remembered`.
function read(key) {
  try {
    return window.localStorage.getItem(key);
  } catch {
    return null;
  }
}

function write(key, value) {
  try {
    if (value === null) window.localStorage.removeItem(key);
    else window.localStorage.setItem(key, value);
  } catch {
    /* A browser that keeps nothing still reads the page. */
  }
}

/// Whether the latch has been lifted in this browser.
export function unlocked() {
  return read(UNLOCK_KEY) === "1";
}

/// Lifts it, if the word is right. Returns whether it was.
export function unlock(word) {
  const right = String(word ?? "").trim().toLowerCase() === PASSWORD;
  if (right) write(UNLOCK_KEY, "1");
  return right;
}

/// The language code of whoever is signed in here, or `null`.
///
/// **The code is the identity.** A tester is one per language, so storing the
/// code rather than the whole record means the roster can be regenerated — a
/// gardener's spelling corrected, a language added — without stranding anybody
/// mid-session in a name that no longer exists.
export function signedIn() {
  return read(STORAGE_KEY);
}

export function signIn(code) {
  write(STORAGE_KEY, code);
}

export function signOut() {
  write(STORAGE_KEY, null);
}

/// The whole record for whoever is signed in, or `null`. Await it; the roster
/// is fetched.
export async function current() {
  const code = signedIn();
  if (!code) return null;
  return (await roster()).find((tester) => tester.code === code) || null;
}

/// Draws the bar that says who you are, above the page, and wires its two
/// controls. Does nothing at all when nobody is signed in, which is why it can
/// be called unconditionally from a page's boot.
///
/// The bar is deliberately the loudest thing on the screen while it is there.
/// The failure this guards against is reading a page in a borrowed language,
/// forgetting, and taking it for the real one — so it is not a discreet corner
/// marker. It says which perspective this is, and it offers the way out.
///
/// `onLeave` is called after signing out, so the page can settle its language
/// again without a reload.
export async function drawBar(onLeave) {
  const tester = await current();
  document.documentElement.toggleAttribute("data-testing", Boolean(tester));
  const existing = document.getElementById("tester-bar");
  if (!tester) {
    existing?.remove();
    return null;
  }

  const bar = existing || document.createElement("div");
  bar.id = "tester-bar";
  bar.className = "tester-bar";
  // The bar is chrome about the page rather than part of it, and it is written
  // in English on purpose: it is the one thing on the screen that must not be
  // in the language being tested, or it stops being legible at exactly the
  // moment it is needed. It is never translated and never commissioned.
  bar.lang = "en";
  bar.dir = "ltr";
  bar.replaceChildren();

  const who = document.createElement("span");
  who.className = "tester-bar__who";
  who.textContent = tester.id;

  const where = document.createElement("span");
  where.className = "tester-bar__where";
  where.textContent = `${tester.name} · ${tester.endonym}`;
  where.lang = tester.code;

  const out = document.createElement("button");
  out.type = "button";
  out.className = "tester-bar__out";
  out.textContent = "Leave";
  out.addEventListener("click", async () => {
    signOut();
    await drawBar(onLeave);
    await onLeave?.();
  });

  bar.append(who, where, out);
  if (!existing) document.body.prepend(bar);
  return tester;
}
